#define CK(x) do{auto e=(x);if(e!=cudaSuccess){std::cerr<<cudaGetErrorString(e)<<"\n";exit(3);}}while(0)
template<class T>std::vector<T>readfile(std::string file){std::ifstream f(file,std::ios::binary|std::ios::ate);size_t bytes=f.tellg();f.seekg(0);std::vector<T>v(bytes/sizeof(T));f.read((char*)v.data(),bytes);return v;}
template<class T>struct Buffer{T*base;int n;T guard;std::vector<T>host;Buffer(std::vector<T>a,T g):n(a.size()),guard(g),host(n+16,g){std::copy(a.begin(),a.end(),host.begin()+8);CK(cudaMalloc(&base,host.size()*sizeof(T)));CK(cudaMemcpy(base,host.data(),host.size()*sizeof(T),cudaMemcpyHostToDevice));}T*data(){return base+8;}void fetch(){CK(cudaMemcpy(host.data(),base,host.size()*sizeof(T),cudaMemcpyDeviceToHost));}void reset(){std::fill(host.begin(),host.end(),guard);CK(cudaMemcpy(base,host.data(),host.size()*sizeof(T),cudaMemcpyHostToDevice));}};
void append(std::vector<double>&o,const std::vector<float2>&v){for(auto a:v){o.push_back(a.x);o.push_back(a.y);}}void append(std::vector<double>&o,const std::vector<float3>&v){for(auto a:v){o.push_back(a.x);o.push_back(a.y);o.push_back(a.z);}}void append(std::vector<double>&o,const std::vector<__half2>&v){for(auto a:v){auto q=__half22float2(a);o.push_back(q.x);o.push_back(q.y);}}void append(std::vector<double>&o,const std::vector<__half>&v){for(auto a:v)o.push_back(__half2float(a));}template<class T>void append(std::vector<double>&o,const std::vector<T>&v){for(auto a:v)o.push_back(a);}
__global__ void params_probe(uint32_t*out,ConstMemParams params){const unsigned char*p=(const unsigned char*)&params;for(int i=0;i<482;i++)out[i]=uint32_t(p[4*i])|(uint32_t(p[4*i+1])<<8)|(uint32_t(p[4*i+2])<<16)|(uint32_t(p[4*i+3])<<24);}
bool validate(const std::vector<double>&got,const std::vector<double>&gold,double&ma,double&mr,double&budget,size_t&exact){size_t off=0;bool ok=true;for(int c=0;c<2;c++){int lengths[3]={256,256,16384},components[3]={2,1,3};for(int kind=0;kind<3;kind++){int n=lengths[kind],k=components[kind],size=(n+16)*k;for(int j=0;j<size;j++){double a=got[off+j],b=gold[off+j];ok &= std::isfinite(a);bool guard=j<8*k||j>=(8+n)*k;bool color=kind==1||(kind==2&&j%3==2);if(guard||color||c==1){exact+=a!=b;ok &= a==b;}else{double e=std::abs(a-b);ma=std::max(ma,e);mr=std::max(mr,e/std::max(std::abs(b),1e-30));double q=e/(0.001953125+0.001953125*std::abs(b));budget=std::max(budget,q);ok &= q<=1;}}off+=size;}}return ok&&off==gold.size();}
int main(){std::string root=std::string(__FILE__).substr(0,std::string(__FILE__).find_last_of('/'));auto fixture=readfile<double>(root+"/fixture.bin"),gold=readfile<double>(root+"/oracle.bin");ConstMemParams pars[2];auto a=readfile<unsigned char>(root+"/params_default.bin"),b=readfile<unsigned char>(root+"/params_linear.bin");memcpy(&pars[0],a.data(),1928);memcpy(&pars[1],b.data(),1928);
 Buffer<float2>start(readfile<float2>(root+"/start.bin"),make_float2(-777,-777));Buffer<float>randoms(readfile<float>(root+"/random.bin"),-777);Buffer<unsigned short>perms(readfile<unsigned short>(root+"/permutations.bin"),0xa5a5);Buffer<__half2>points(std::vector<__half2>(256),__floats2half2_rn(-777,-777));Buffer<__half>colors(std::vector<__half>(256),__float2half_rn(-777));Buffer<float3>vertices(std::vector<float3>(16384),make_float3(-777,-777,-777));uint32_t*probe;CK(cudaMalloc(&probe,482*4));std::vector<uint32_t>pw(482);
 auto frame=[&](const ConstMemParams&p){kernel_initialize<<<8,32>>>(points.data(),colors.data(),perms.data(),0,start.data(),randoms.data(),p);CK(cudaDeviceSynchronize());for(int s=1;s<=15;s++){kernel_iterate<<<8,32>>>(points.data(),colors.data(),perms.data(),s,randoms.data(),p);CK(cudaDeviceSynchronize());}kernel_generate_points<<<8,32>>>(vertices.data(),points.data(),colors.data(),perms.data(),16,randoms.data(),p);CK(cudaDeviceSynchronize());};for(auto&p:pars){params_probe<<<1,1>>>(probe,p);frame(p);}CK(cudaDeviceSynchronize());
 for(int trial=1;trial<=5;trial++){std::vector<double>words;for(auto&p:pars){params_probe<<<1,1>>>(probe,p);CK(cudaMemcpy(pw.data(),probe,482*4,cudaMemcpyDeviceToHost));append(words,pw);}start.fetch();randoms.fetch();perms.fetch();std::vector<double>prefix{256,64,15,1024,128,2};prefix.insert(prefix.end(),words.begin(),words.end());std::vector<float2>s(start.host.begin()+8,start.host.end()-8);std::vector<float>r(randoms.host.begin()+8,randoms.host.end()-8);std::vector<unsigned short>t(perms.host.begin()+8,perms.host.end()-8);append(prefix,s);append(prefix,r);append(prefix,t);std::vector<double>echo=words;append(echo,start.host);append(echo,randoms.host);append(echo,perms.host);
 std::vector<double>got,times;double elapsed=0;for(auto&p:pars){points.reset();colors.reset();vertices.reset();CK(cudaDeviceSynchronize());auto stamp=std::chrono::steady_clock::now();frame(p);double dt=std::chrono::duration<double>(std::chrono::steady_clock::now()-stamp).count();elapsed+=dt;times.push_back(dt);points.fetch();colors.fetch();vertices.fetch();append(got,points.host);append(got,colors.host);append(got,vertices.host);}double ma=0,mr=0,budget=0;size_t exact=0;bool inputguards=true;for(int g=0;g<8;g++){for(int j:{g,256+8+g})inputguards &= start.host[j].x==-777&&start.host[j].y==-777;for(int j:{g,1024+8+g})inputguards &= randoms.host[j]==-777;for(int j:{g,32768+8+g})inputguards &= perms.host[j]==0xa5a5;}bool ok=validate(got,gold,ma,mr,budget,exact)&&prefix==fixture&&inputguards;std::vector<double>output=prefix;output.insert(output.end(),got.begin(),got.end());output.insert(output.end(),echo.begin(),echo.end());std::string file="output_trial"+std::to_string(trial)+".bin";std::ofstream f(file,std::ios::binary);f.write((char*)output.data(),output.size()*8);f.close();std::cout<<std::setprecision(17)<<"STUDY_TRIAL {\"trial\":"<<trial<<",\"time_seconds\":"<<elapsed<<",\"correct\":"<<(ok?"true":"false")<<",\"checked_values\":"<<output.size()<<",\"max_abs_error\":"<<ma<<",\"max_rel_error\":"<<mr<<",\"max_engineering_budget_fraction\":"<<budget<<",\"exact_color_guard_linear_mismatches\":"<<exact<<",\"path_times_seconds\":["<<times[0]<<","<<times[1]<<"],\"timing_region\":\"sum2_full_frame_17kernel_hostinclusive_regions\",\"jit_excluded\":true,\"internal_repeats\":1,\"output_artifact\":{\"path\":\""<<file<<"\",\"dtype\":\"float64\",\"count\":"<<output.size()<<",\"byte_order\":\"little\"}}\n";}
